package com.bank.serde.registry;

import java.util.HashMap;
import java.util.Map;

// Simulates the Confluent Schema Registry: assigns a small integer id per schema
// and returns the schema by id. The real registry does this over HTTP.
public class SchemaRegistry {
    private final Map<String, Integer> schemaToId = new HashMap<>();
    private final Map<Integer, String> idToSchema = new HashMap<>();
    private int nextId = 1;

    public synchronized int register(String subject, String schema) {
        String key = subject + "|" + schema;
        return schemaToId.computeIfAbsent(key, k -> {
            int id = nextId++;
            idToSchema.put(id, schema);
            return id;
        });
    }

    public String getById(int id) {
        String schema = idToSchema.get(id);
        if (schema == null) throw new IllegalStateException("No schema for id " + id);
        return schema;
    }
}
