package com.bank.serde.serde;

import com.bank.serde.model.Transfer;
import com.bank.serde.registry.SchemaRegistry;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;

// Mirrors the Confluent wire format: [magic byte 0][4-byte schema id][payload].
public class TransferSerializer {
    public static final byte MAGIC_BYTE = 0x0;
    private static final String SCHEMA =
        "{\"type\":\"record\",\"name\":\"Transfer\",\"fields\":[from,to,amount,currency]}";

    private final SchemaRegistry registry;
    private final int schemaId;

    public TransferSerializer(SchemaRegistry registry, String subject) {
        this.registry = registry;
        this.schemaId = registry.register(subject, SCHEMA);
    }

    public byte[] serialize(Transfer t) {
        // payload is a compact field-ordered encoding (real Avro is binary too)
        String payload = t.getFromId() + "|" + t.getToId() + "|"
                       + t.getAmount().toPlainString() + "|" + t.getCurrency();
        byte[] body = payload.getBytes(StandardCharsets.UTF_8);

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(MAGIC_BYTE);                 // 1 byte
        out.write((schemaId >>> 24) & 0xFF);   // 4-byte big-endian id
        out.write((schemaId >>> 16) & 0xFF);
        out.write((schemaId >>> 8) & 0xFF);
        out.write(schemaId & 0xFF);
        out.write(body, 0, body.length);
        return out.toByteArray();
    }
}
