package com.bank.serde.serde;

import com.bank.serde.model.Transfer;
import com.bank.serde.registry.SchemaRegistry;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;

public class TransferDeserializer {
    private final SchemaRegistry registry;

    public TransferDeserializer(SchemaRegistry registry) { this.registry = registry; }

    public Transfer deserialize(byte[] data) {
        if (data == null || data.length < 5 || data[0] != TransferSerializer.MAGIC_BYTE) {
            // This is the real-world "Unknown magic byte" condition.
            throw new IllegalArgumentException("Unknown magic byte! This record was not "
                + "written by the schema-registry serializer (maybe old JSON).");
        }
        int id = ((data[1] & 0xFF) << 24) | ((data[2] & 0xFF) << 16)
               | ((data[3] & 0xFF) << 8) | (data[4] & 0xFF);
        registry.getById(id); // confirm the schema exists (we would decode with it)

        String payload = new String(data, 5, data.length - 5, StandardCharsets.UTF_8);
        String[] p = payload.split("\\|");
        return new Transfer(p[0], p[1], new BigDecimal(p[2]), p[3]);
    }
}
