package com.bank.serde;

import com.bank.serde.model.Transfer;
import com.bank.serde.registry.SchemaRegistry;
import com.bank.serde.serde.TransferDeserializer;
import com.bank.serde.serde.TransferSerializer;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.logging.*;

public class SerdeDemo {
    private static final Logger log = Logger.getLogger(SerdeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SchemaRegistry registry = new SchemaRegistry();
        TransferSerializer serializer = new TransferSerializer(registry, "transfers-value");
        TransferDeserializer deserializer = new TransferDeserializer(registry);

        Transfer t = new Transfer("SAV2001", "CUR3001", new BigDecimal("50000"), "INR");
        byte[] wire = serializer.serialize(t);
        log.info(() -> "Serialized " + t + " to " + wire.length + " bytes, magic=" + wire[0]);

        Transfer back = deserializer.deserialize(wire);
        log.info(() -> "Deserialized back: " + back);

        // Now simulate a stray OLD JSON record left on the same topic.
        byte[] oldJson = "{\"from\":\"SAV2001\",\"amt\":50000}".getBytes(StandardCharsets.UTF_8);
        try {
            deserializer.deserialize(oldJson);
        } catch (IllegalArgumentException ex) {
            log.log(Level.SEVERE, "Poison record on topic (first byte=" + oldJson[0] + ")", ex);
            log.warning("Resolution: quarantine to DLQ, do NOT crash the consumer loop.");
        }
    }
}

